"""Provider-neutral AURA Chat v1 service.

Only injected dependencies can talk to a model, the web, or storage.  Importing
this module performs no I/O and starts no background task.
"""
from __future__ import annotations
import asyncio
from dataclasses import dataclass, replace
from time import monotonic
from typing import Awaitable, Protocol, Sequence, TypeVar
from core.chat_contract import CHAT_STAGE_HISTORY, CHAT_STAGE_INPUT, CHAT_STAGE_MODEL, CHAT_STAGE_PERSIST, CHAT_STAGE_WEB, ChatRequest, ChatResult, ChatStatus, ContentCheck, OutwardContent, SourceCitation, valid_citations
from core.kiem_tien import gan_canh_bao
from core.loai_cau_hoi import SANG_TAC as LOAI_SANG_TAC, TRA_CUU as LOAI_TRA_CUU, TU_NGHI as LOAI_TU_NGHI, loai as loai_cau_hoi
from core.web_search import mang_co_song, is_search_request, la_chuyen_rieng_cua_sep, la_viec_tu_lam

@dataclass(frozen=True, slots=True)
class ChatMessage:
    role: str
    content: str

@dataclass(frozen=True, slots=True)
class ModelReply:
    text: str
    requires_web: bool = False
    search_query: str = ''

class ModelGateway(Protocol):
    """An async, cancellation-aware model adapter."""

    async def generate(self, request: ChatRequest, *, history: Sequence[ChatMessage], sources: Sequence[SourceCitation]=()) -> ModelReply:
        ...

class WebSearchGateway(Protocol):

    async def search(self, query: str) -> Sequence[SourceCitation]:
        ...

class SessionStore(Protocol):
    """Cancellation-aware storage; append should be atomic in its adapter."""

    async def load(self, *, actor_id: str, session_id: str) -> Sequence[ChatMessage]:
        ...

    async def append_exchange(self, *, request: ChatRequest, result: ChatResult) -> None:
        ...

class FreshnessPolicy(Protocol):

    def requires_web(self, request: ChatRequest) -> bool:
        ...

class ContentGuard(Protocol):
    """Local safety boundary; concrete legacy guards are wired by adapters."""

    def check_input(self, request: ChatRequest) -> ContentCheck:
        ...

    def scrub_history(self, history: Sequence[ChatMessage]) -> Sequence[ChatMessage]:
        ...

    def scrub_output(self, content: OutwardContent) -> OutwardContent:
        ...

class DeterministicFreshnessPolicy:
    """Shared deterministic web policy plus inherently live domains.

    ``core.web_search.is_search_request`` is the authoritative lexical policy
    used by the existing read-only search boundary. Calling it performs no
    network or filesystem I/O. Weather is inherently live even when the user
    omits words such as "today", so it is the one domain-level addition here.
    """
    _EXPLICIT_COMMANDS = ('tra ', 'tìm ', 'kiểm tra', 'search ', 'lookup ', 'check ', 'verify ')
    _INHERENTLY_LIVE_DOMAINS = ('thời tiết', 'weather')

    def requires_web(self, request: ChatRequest) -> bool:
        PHONG_SANG_NHAN = {'viet': LOAI_SANG_TAC, 'tra': LOAI_TRA_CUU, 'sua': LOAI_TU_NGHI}
        nhan = _.get(request.phong) or loai_cau_hoi(request.text)
        if nhan == LOAI_TRA_CUU:
            return True
        if nhan == LOAI_SANG_TAC:
            return False
        normalized = request.text.casefold()
        if la_viec_tu_lam(request.text) and (not is_search_request(request.text)):
            return False
        return is_search_request(request.text) or any((command in normalized for command in self._EXPLICIT_COMMANDS)) or any((domain in normalized for domain in self._INHERENTLY_LIVE_DOMAINS))

class _NullWebSearch:

    async def search(self, query: str) -> Sequence[SourceCitation]:
        return ()
_AN_HAN_GHI_SO = 2.0
_HAN_GIO_CO_NGUON = 180.0
_MAT_MANG = '📡 Máy đang KHÔNG có mạng nên em không tra được — chứ không phải nguồn kém.\nSếp kiểm lại wifi giúp em rồi hỏi lại. Những câu không cần dữ liệu mới thì em vẫn trả lời được bình thường ngay lúc này.'
_WEB_SENTINEL = '[[AURA_REQUIRES_WEB]]'

def _bo_co_noi_bo(value: object) -> str:
    """Remove the web-routing sentinel from any user-visible text."""
    if not isinstance(value, str):
        return ''
    return value.replace(_WEB_SENTINEL, '').strip()
_QUEN_DAU_CHUYEN = '😅 Em không trả lời được câu này — và nhiều khả năng là do em QUÊN chứ không phải không biết: cuộc trò chuyện đã dài hơn phần em còn giữ trong đầu.\nSếp nhắc lại giúp em dữ kiện đó một câu thôi, em trả lời được ngay.'
_CO_NGUON_MA_CHUA_DAM_CHOT = '🔎 Em tra được {so} nguồn nhưng chưa dám chốt một con số từ chúng — các nguồn nói lệch nhau hoặc em đọc chưa chắc.\nEm để nguyên nguồn bên dưới, Sếp xem trực tiếp cho chắc ạ.'
_MESSAGES = {ChatStatus.REJECTED: 'Yêu cầu không hợp lệ nên AURA chưa xử lý.', ChatStatus.CANNOT_ANSWER: 'AURA chưa thể trả lời câu này một cách đáng tin cậy.', ChatStatus.WEB_UNAVAILABLE: 'Câu này cần tra nguồn mới, nhưng AURA chưa lấy đủ nguồn đáng tin cậy.', ChatStatus.BACKEND_ERROR: 'AURA đang gặp lỗi ở bộ não. Vui lòng thử lại sau.', ChatStatus.TIMEOUT: 'AURA đã dừng vì quá thời gian trả lời.', ChatStatus.CANCELLED: 'Yêu cầu đã được hủy.'}

def _safe_user_message(error: BaseException) -> str | None:
    """Câu an toàn do tầng dưới gửi lên, nếu có.

    Cố ý đọc bằng `getattr` chứ không import lớp lỗi của nhà cung cấp: tầng
    service phải trung lập với backend.  Chỉ nhận chuỗi khác rỗng, và vẫn để
    `_finalize` cho nó đi qua bộ che.
    """
    message = getattr(error, 'user_message', None)
    if isinstance(message, str) and message.strip():
        return message
    return None
_PERSISTENCE_ERROR_MESSAGE = 'AURA đã tạo câu trả lời nhưng không xác nhận được việc lưu lịch sử. Vui lòng thử lại.'

class _DeadlineExceeded(Exception):
    pass

class _WebUnavailable(Exception):
    pass
_T = TypeVar('_T')

def _consume_background_result(task: asyncio.Task[object]) -> None:
    """Retrieve a late task result so it cannot emit an unhandled warning."""
    try:
        task.result()
    except (BaseException,):
        pass

async def _before_deadline(awaitable: Awaitable[_T], deadline: float) -> _T:
    """Race one awaitable against a service-owned monotonic deadline.

    Unlike ``wait_for``, this function does not accept a value returned after
    cancellation as an on-time result.  Cancellation is cooperative: adapters
    must stop promptly when cancelled.  An adapter around a non-cancellable
    SDK belongs behind a separately terminable process boundary; arbitrary
    Python coroutines cannot be forcibly killed here.
    """
    remaining = deadline - monotonic()
    if remaining <= 0:
        close = getattr(awaitable, 'close', None)
        if close is not None:
            close()
        raise _DeadlineExceeded
    task: asyncio.Task[_T] = asyncio.create_task(awaitable)
    try:
        done, _ = await asyncio.wait((task,), timeout=remaining)
    except asyncio.CancelledError:
        task.cancel()
        task.add_done_callback(_consume_background_result)
        raise
    if task not in done:
        task.cancel()
        task.add_done_callback(_consume_background_result)
        raise _DeadlineExceeded
    return task.result()

class ChatService:
    """One deterministic front door shared by every chat channel."""

    def __init__(self, *, model: ModelGateway, store: SessionStore, guard: ContentGuard, web: WebSearchGateway | None=None, freshness_policy: FreshnessPolicy | None=None, timeout_s: float=20.0) -> None:
        if timeout_s <= 0:
            raise ValueError('timeout_s must be positive')
        self._model = model
        self._store = store
        self._guard = guard
        self._web = web if web is not None else _NullWebSearch()
        self._freshness = freshness_policy if freshness_policy is not None else DeterministicFreshnessPolicy()
        self._timeout_s = float(timeout_s)

    async def reply(self, request: ChatRequest) -> ChatResult:
        started = monotonic()
        deadline = started + self._timeout_s
        stage = CHAT_STAGE_INPUT
        if request.validation_errors():
            return await self._finalize(request, ChatStatus.REJECTED, started=started, deadline=deadline, stage=stage)
        da_goi_mang = False
        safe_request = request
        try:
            content_check = self._guard.check_input(request)
            if not isinstance(content_check, ContentCheck) or content_check.validation_errors():
                raise TypeError('ContentGuard returned an invalid ContentCheck')
            if not content_check.allowed:
                return await self._finalize(request, ChatStatus.REJECTED, text=content_check.rejection_text, started=started, deadline=deadline, stage=stage)
            safe_request = replace(request, text=content_check.transcript_text)
            stage = CHAT_STAGE_HISTORY
            raw_history = tuple(await _before_deadline(self._store.load(actor_id=safe_request.actor_id, session_id=safe_request.session_id), deadline))
            history = tuple(self._guard.scrub_history(raw_history))
            if not all((isinstance(item, ChatMessage) for item in history)):
                raise TypeError('ContentGuard returned invalid history')
            policy_requires_web = self._freshness.requires_web(safe_request)
            sources: tuple[SourceCitation, ...] = ()
            if policy_requires_web:
                deadline = max(deadline, started + _HAN_GIO_CO_NGUON)
                da_goi_mang = True
                stage = CHAT_STAGE_WEB
                sources = await self._search_with_evidence(safe_request, deadline)
                stage = CHAT_STAGE_MODEL
                final_reply = await _before_deadline(self._model.generate(safe_request, history=history, sources=sources), deadline)
            else:
                stage = CHAT_STAGE_MODEL
                initial = await _before_deadline(self._model.generate(safe_request, history=history), deadline)
                final_reply = initial
                if initial.requires_web and (la_chuyen_rieng_cua_sep(safe_request.text) or la_viec_tu_lam(safe_request.text)):
                    return await self._finalize(request, ChatStatus.CANNOT_ANSWER, text=self._loi_bo_tay(history), started=started, deadline=deadline, stage=stage)
                if initial.requires_web:
                    da_goi_mang = True
                    stage = CHAT_STAGE_WEB
                    sources = await self._search_with_evidence(safe_request, deadline, search_query=initial.search_query)
                    stage = CHAT_STAGE_MODEL
                    final_reply = await _before_deadline(self._model.generate(safe_request, history=history, sources=sources), deadline)
            if final_reply.requires_web and sources:
                return await self._finalize(request, ChatStatus.CANNOT_ANSWER, text=self._loi_bo_tay(history, sources), used_web=da_goi_mang, sources=sources, started=started, deadline=deadline, persist=True, transcript_request=safe_request, stage=stage)
            text = _bo_co_noi_bo(final_reply.text)
            text = gan_canh_bao(text)
            if not text:
                return await self._finalize(request, ChatStatus.CANNOT_ANSWER, text=self._loi_bo_tay(history, sources), used_web=da_goi_mang, sources=sources, started=started, deadline=deadline, persist=True, transcript_request=safe_request, stage=stage)
            return await self._finalize(request, ChatStatus.OK, text=text, used_web=da_goi_mang, sources=sources, started=started, deadline=deadline, persist=True, transcript_request=safe_request, stage=stage)
        except _DeadlineExceeded:
            return await self._finalize(request, ChatStatus.TIMEOUT, used_web=da_goi_mang, started=started, deadline=deadline, persist=True, transcript_request=safe_request, persist_deadline=monotonic() + _AN_HAN_GHI_SO, stage=stage)
        except _WebUnavailable:
            return await self._finalize(request, ChatStatus.WEB_UNAVAILABLE, text=None if mang_co_song() else _MAT_MANG, used_web=da_goi_mang, started=started, deadline=deadline, persist=True, transcript_request=safe_request, stage=stage)
        except asyncio.CancelledError:
            return await self._finalize(request, ChatStatus.CANCELLED, used_web=da_goi_mang, started=started, deadline=deadline, stage=stage)
        except Exception as error:
            return await self._finalize(request, ChatStatus.BACKEND_ERROR, started=started, deadline=deadline, text=_safe_user_message(error), used_web=da_goi_mang, stage=stage)

    async def _search_with_evidence(self, request: ChatRequest, deadline: float, *, search_query: str='') -> tuple[SourceCitation, ...]:
        query = (search_query or '').strip() or request.text
        try:
            found = await _before_deadline(self._web.search(query), deadline)
            sources = valid_citations(found)
        except (_DeadlineExceeded, asyncio.CancelledError):
            raise
        except Exception as error:
            raise _WebUnavailable from error
        if len(sources) < 2:
            raise _WebUnavailable
        return sources

    def _loi_bo_tay(self, history: Sequence[ChatMessage], sources: Sequence[SourceCitation]=()) -> str | None:
        """Bó tay vì QUÊN, hay bó tay vì KHÔNG BIẾT — nói đúng cái nào đang xảy ra.

        Không hỏi model "bạn có quên không" (nó không tự biết, và hỏi thêm một
        lượt nữa thì vừa chậm vừa không kiểm lại được).  Chỉ so hai con số đã
        có sẵn: sổ phiên giữ được bao nhiêu tin, và cổng model nhìn thấy được
        bao nhiêu.  Sổ dài hơn tầm nhìn nghĩa là CÓ đoạn đã rơi ra ngoài.

        Trả `None` khi không có gì rơi — để `_finalize` dùng câu mặc định.
        """
        if sources:
            return _CO_NGUON_MA_CHUA_DAM_CHOT.format(so=len(sources))
        tam_nhin = getattr(self._model, 'history_window', 0)
        if not isinstance(tam_nhin, int) or tam_nhin <= 0:
            return None
        return _QUEN_DAU_CHUYEN if len(history) > tam_nhin else None

    async def _finalize(self, request: ChatRequest, status: ChatStatus, *, started: float, deadline: float, text: str | None=None, used_web: bool=False, sources: tuple[SourceCitation, ...]=(), persist: bool=False, transcript_request: ChatRequest | None=None, persist_deadline: float | None=None, stage: str='') -> ChatResult:
        """Scrub exactly once, then optionally expose only scrubbed data to storage."""
        raw_text = _bo_co_noi_bo(text) if text is not None else ''
        if status is ChatStatus.OK and text is not None and (not raw_text):
            status = ChatStatus.CANNOT_ANSWER
        raw_text = raw_text or _MESSAGES[status]
        raw_outward = OutwardContent(text=raw_text, sources=sources, fallback_text=_MESSAGES[ChatStatus.WEB_UNAVAILABLE])
        try:
            safe_outward = self._guard.scrub_output(raw_outward)
        except Exception:
            safe_outward = OutwardContent(text='AURA không thể xuất câu trả lời an toàn.')
        if not isinstance(safe_outward, OutwardContent):
            safe_outward = OutwardContent(text='AURA không thể xuất câu trả lời an toàn.')
        safe_text = _bo_co_noi_bo(safe_outward.text)
        if not safe_text:
            safe_text = 'AURA không thể xuất câu trả lời an toàn.'
        safe_sources: tuple[SourceCitation, ...] = ()
        if len(safe_outward.sources) == len(sources):
            candidates: list[SourceCitation] = []
            for original, candidate in zip(sources, safe_outward.sources):
                if not isinstance(candidate, SourceCitation):
                    continue
                if candidate.url != original.url:
                    continue
                candidates.append(candidate)
            safe_sources = valid_citations(candidates)
        if status is ChatStatus.OK and used_web and (len(safe_sources) < 2):
            status = ChatStatus.WEB_UNAVAILABLE
            safe_sources = ()
            fallback = _bo_co_noi_bo(safe_outward.fallback_text)
            safe_text = fallback if fallback else 'AURA không thể xuất câu trả lời an toàn.'
            persist = False
        if status is ChatStatus.REJECTED:
            persist = False
        latency_ms = max(0, round((monotonic() - started) * 1000))
        result = ChatResult(request_id=request.request_id, session_id=request.session_id, status=status, text=safe_text, used_web=used_web, sources=safe_sources, latency_ms=latency_ms, stage=stage)
        if persist:
            if transcript_request is None:
                raise ValueError('transcript_request is required when persist=True')
            try:
                await _before_deadline(self._store.append_exchange(request=transcript_request, result=result), deadline if persist_deadline is None else persist_deadline)
            except (_DeadlineExceeded, asyncio.CancelledError):
                raise
            except Exception:
                try:
                    failure_outward = self._guard.scrub_output(OutwardContent(text=_PERSISTENCE_ERROR_MESSAGE))
                except Exception:
                    failure_outward = OutwardContent(text='AURA không thể xuất câu trả lời an toàn.')
                failure_text = _bo_co_noi_bo(failure_outward.text if isinstance(failure_outward, OutwardContent) else '')
                failure_text = failure_text or 'AURA không thể xuất câu trả lời an toàn.'
                return ChatResult(request_id=request.request_id, session_id=request.session_id, status=ChatStatus.BACKEND_ERROR, text=failure_text, used_web=used_web, sources=(), stage=CHAT_STAGE_PERSIST, latency_ms=max(0, round((monotonic() - started) * 1000)))
        return result

