from core.chat_contract import CHAT_STAGE_HISTORY, CHAT_STAGE_INPUT, CHAT_STAGE_MODEL, CHAT_STAGE_PERSIST, CHAT_STAGE_WEB, ChatRequest, ChatResult, ChatStatus, ContentCheck, OutwardContent, SourceCitation, valid_citations
from core.kiem_tien import gan_canh_bao
from core.loai_cau_hoi import SANG_TAC as LOAI_SANG_TAC, TRA_CUU as LOAI_TRA_CUU, TU_NGHI as LOAI_TU_NGHI, loai as loai_cau_hoi
from core.web_search import mang_co_song, is_search_request, la_chuyen_rieng_cua_sep, la_viec_tu_lam

@dataclass(frozen=True, slots=True)
class ChatMessage:
    role: str
    content: str

@dataclass(frozen=True, slots=True)
class ModelReply:
    text: str
    requires_web: bool = False
    search_query: str = ''

class ModelGateway(Protocol):
    """An async, cancellation-aware model adapter."""

    async def generate(self, request: ChatRequest, *, history: Sequence[ChatMessage], sources: Sequence[SourceCitation]=()) -> ModelReply:
        ...

class WebSearchGateway(Protocol):

    async def search(self, query: str) -> Sequence[SourceCitation]:
        ...

class SessionStore(Protocol):
    """Cancellation-aware storage; append should be atomic in its adapter."""

    async def load(self, *, actor_id: str, session_id: str) -> Sequence[ChatMessage]:
        ...

    async def append_exchange(self, *, request: ChatRequest, result: ChatResult) -> None:
        ...

class FreshnessPolicy(Protocol):

    def requires_web(self, request: ChatRequest) -> bool:
        ...

class ContentGuard(Protocol):
    """Local safety boundary; concrete legacy guards are wired by adapters."""

    def check_input(self, request: ChatRequest) -> ContentCheck:
        ...

    def scrub_history(self, history: Sequence[ChatMessage]) -> Sequence[ChatMessage]:
        ...

    def scrub_output(self, content: OutwardContent) -> OutwardContent:
        ...

class DeterministicFreshnessPolicy:
    """Shared deterministic web policy plus inherently live domains.

    ``core.web_search.is_search_request`` is the authoritative lexical policy
    used by the existing read-only search boundary. Calling it performs no
    network or filesystem I/O. Weather is inherently live even when the user
    omits words such as "today", so it is the one domain-level addition here.
    """
    _EXPLICIT_COMMANDS = ('tra ', 'tìm ', 'kiểm tra', 'search ', 'lookup ', 'check ', 'verify ')
    _INHERENTLY_LIVE_DOMAINS = ('thời tiết', 'weather')

    def requires_web(self, request: ChatRequest) -> bool:
        PHONG_SANG_NHAN = {'viet': LOAI_SANG_TAC, 'tra': LOAI_TRA_CUU, 'sua': LOAI_TU_NGHI}
        nhan = PHONG_SANG_NHAN.get(request.phong) or loai_cau_hoi(request.text)
        if nhan == LOAI_TRA_CUU:
            return True
        if nhan == LOAI_SANG_TAC:
            return False
        normalized = request.text.casefold()
        if la_viec_tu_lam(request.text) and (not is_search_request(request.text)):
            return False
        return is_search_request(request.text) or any((command in normalized for command in self._EXPLICIT_COMMANDS)) or any((domain in normalized for domain in self._INHERENTLY_LIVE_DOMAINS))

