@dataclass
class TheNode:
    id: str
    ma: str
    o: Dict[str, str] = field(default_factory=dict)
    than: List[TheNode] = field(default_factory=list)
    line_start: Optional[int] = None
    line_end: Optional[int] = None
    indent: int = 0
    duoi_dong: str = ''
    raw_text: Optional[str] = None
    da_sua: bool = False

    def to_dict(self) -> Dict[str, Any]:
        res: Dict[str, Any] = {'id': self.id, 'ma': self.ma, 'o': dict(self.o), 'than': [child.to_dict() for child in self.than], 'line_start': self.line_start, 'line_end': self.line_end, 'indent': self.indent, 'duoi_dong': self.duoi_dong, 'raw_text': self.raw_text, 'da_sua': self.da_sua}
        return res

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> TheNode:
        than_list = [cls.from_dict(child) for child in data.get('than', [])]
        return cls(id=data.get('id', ''), ma=data.get('ma', 'ma_tho'), o=dict(data.get('o', {})), than=than_list, line_start=data.get('line_start'), line_end=data.get('line_end'), indent=data.get('indent', 0), duoi_dong=data.get('duoi_dong', ''), raw_text=data.get('raw_text'), da_sua=data.get('da_sua', False))

@dataclass
class FileSourceRecord:
    duong_dan: Optional[str]
    raw_bytes: bytes
    newline: str
    lines: List[str]
    tree: List[TheNode]
    has_modifications: bool = False

def _tach_dong_va_newline(raw_bytes: bytes) -> Tuple[List[str], str]:
    """Tách bytes thành danh sách dòng và phát hiện kiểu xuống dòng gốc."""
    text = raw_bytes.decode('utf-8', errors='replace')
    newline = '\r\n' if '\r\n' in text else '\n'
    lines = text.split(newline)
    return (lines, newline)

def _trich_duoi_dong(line: str, end_col: Optional[int]) -> str:
    """Trích xuất duoi_dong bằng end_col_offset của AST.

    Cực kỳ quan trọng (Mục 15):
    Trong CPython AST, col_offset và end_col_offset là UTF-8 BYTE OFFSET tính từ
    đầu dòng (chứ không phải character offset). Nếu dòng chứa ký tự Unicode đa byte
    (như tiếng Việt, em-dash), phải cắt trên chuỗi bytes UTF-8 rồi mới decode lại.
    """
    if end_col is None or end_col < 0:
        return ''
    line_bytes = line.encode('utf-8')
    if end_col >= len(line_bytes):
        return ''
    duoi_bytes = line_bytes[end_col:]
    return duoi_bytes.decode('utf-8', errors='replace')

def _la_dong_ma_thuat(line: str, line_no: int) -> bool:
    """Dòng 1-2 mà khớp coding[:=] hoặc bắt đầu bằng #! thì là dòng ma thuật."""
    if line_no in (1, 2):
        s = line.strip()
        if s.startswith('#!'):
            return True
        if 'coding' in s and re.search('coding[=:]\\s*([-\\w.]+)', s):
            return True
    return False

def _tao_id(prefix: str, idx: int) -> str:
    return f'{prefix}_{idx}_{int(time.time() * 1000) % 1000000}'

def _phan_tich_ast_statement(node: ast.AST, lines: List[str], full_source: str, counter: List[int]) -> Optional[TheNode]:
    """Cố gắng chuyển một AST statement sang 1 trong 10 thẻ chuẩn.
    Nếu không khớp, trả về None để caller chuyển thành thẻ `ma_tho`.
    """
    counter[0] += 1
    node_id = _tao_id('the', counter[0])
    l_start = getattr(node, 'lineno', 1)
    l_end = getattr(node, 'end_lineno', l_start)
    col_offset = getattr(node, 'col_offset', 0)
    end_col = getattr(node, 'end_col_offset', None)
    line_text = lines[l_start - 1] if 0 <= l_start - 1 < len(lines) else ''
    duoi_dong = _trich_duoi_dong(line_text, end_col) if l_start == l_end else ''
    indent = col_offset
    if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
        target_name = node.targets[0].id
        val_seg = ast.get_source_segment(full_source, node.value) or ''
        return TheNode(id=node_id, ma='gan', o={'ten_bien': target_name, 'gia_tri': val_seg}, than=[], line_start=l_start, line_end=l_end, indent=indent, duoi_dong=duoi_dong)
    if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call) and isinstance(node.value.func, ast.Name) and (node.value.func.id == 'print'):
        call_node = node.value
        args_text = ''
        if call_node.args:
            seg = ast.get_source_segment(full_source, call_node)
            if seg and '(' in seg and seg.endswith(')'):
                args_text = seg[seg.find('(') + 1:-1].strip()
        return TheNode(id=node_id, ma='in_ra', o={'noi_dung': args_text}, than=[], line_start=l_start, line_end=l_end, indent=indent, duoi_dong=duoi_dong)
    if isinstance(node, ast.Return):
        val_seg = ''
        if node.value is not None:
            val_seg = ast.get_source_segment(full_source, node.value) or ''
        return TheNode(id=node_id, ma='tra_ve', o={'gia_tri': val_seg}, than=[], line_start=l_start, line_end=l_end, indent=indent, duoi_dong=duoi_dong)
    if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call) and isinstance(node.value.func, ast.Name) and (node.value.func.id != 'print'):
        fn_name = node.value.func.id
        call_seg = ast.get_source_segment(full_source, node.value) or ''
        args_text = ''
        if '(' in call_seg and call_seg.endswith(')'):
            args_text = call_seg[call_seg.find('(') + 1:-1].strip()
        return TheNode(id=node_id, ma='goi_ham', o={'ten_ham': fn_name, 'doi_so': args_text}, than=[], line_start=l_start, line_end=l_end, indent=indent, duoi_dong=duoi_dong)
    if isinstance(node, ast.Expr) and isinstance(node.value, ast.BinOp):
        bin_op = node.value
        trai = ast.get_source_segment(full_source, bin_op.left) or ''
        phai = ast.get_source_segment(full_source, bin_op.right) or ''
        op_map = {ast.Add: '+', ast.Sub: '-', ast.Mult: '*', ast.Div: '/', ast.FloorDiv: '//', ast.Mod: '%', ast.Pow: '**'}
        phep = op_map.get(type(bin_op.op), '+')
        return TheNode(id=node_id, ma='pheptinh', o={'trai': trai, 'phep': phep, 'phai': phai}, than=[], line_start=l_start, line_end=l_end, indent=indent, duoi_dong=duoi_dong)
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        fn_name = node.name
        params = [arg.arg for arg in node.args.args]
        ret_str = ast.unparse(node.returns) if getattr(node, 'returns', None) is not None else ''
        body_nodes = _chuyen_danh_sach_ast_sang_the(node.body, lines, full_source, counter)
        o_dict = {'ten_ham': fn_name, 'tham_so': ', '.join(params)}
        if ret_str:
            o_dict['kieu_tra_ve'] = ret_str
        if isinstance(node, ast.AsyncFunctionDef):
            o_dict['async'] = '1'
        if getattr(node, 'decorator_list', None):
            o_dict['trang_tri'] = '\n'.join((ast.unparse(d) for d in node.decorator_list))
        return TheNode(id=node_id, ma='ham', o=o_dict, than=body_nodes, line_start=l_start, line_end=l_end, indent=indent, duoi_dong=duoi_dong)
    if isinstance(node, ast.For) and (not node.orelse):
        target_str = ast.get_source_segment(full_source, node.target) or ''
        iter_str = ast.get_source_segment(full_source, node.iter) or ''
        body_nodes = _chuyen_danh_sach_ast_sang_the(node.body, lines, full_source, counter)
        return TheNode(id=node_id, ma='lap_moi', o={'bien': target_str, 'day': iter_str}, than=body_nodes, line_start=l_start, line_end=l_end, indent=indent, duoi_dong=duoi_dong)
    if isinstance(node, ast.While) and (not node.orelse):
        cond_str = ast.get_source_segment(full_source, node.test) or ''
        body_nodes = _chuyen_danh_sach_ast_sang_the(node.body, lines, full_source, counter)
        return TheNode(id=node_id, ma='lap_khi', o={'dieu_kien': cond_str}, than=body_nodes, line_start=l_start, line_end=l_end, indent=indent, duoi_dong=duoi_dong)
    if isinstance(node, ast.If):
        cond_str = ast.get_source_segment(full_source, node.test) or ''
        body_nodes = _chuyen_danh_sach_ast_sang_the(node.body, lines, full_source, counter)
        if_end = getattr(node.body[-1], 'end_lineno', l_end) if node.body else l_end
        if_node = TheNode(id=node_id, ma='neu', o={'dieu_kien': cond_str}, than=body_nodes, line_start=l_start, line_end=if_end, indent=indent, duoi_dong=duoi_dong)
        if node.orelse:
            counter[0] += 1
            else_id = _tao_id('the', counter[0])
            else_body = _chuyen_danh_sach_ast_sang_the(node.orelse, lines, full_source, counter)
            else_start = getattr(node.orelse[0], 'lineno', if_end + 1)
            actual_else_start = else_start
            for check_l in range(if_end + 1, else_start + 1):
                if check_l <= len(lines) and 'else:' in lines[check_l - 1]:
                    actual_else_start = check_l
                    break
            else_end = getattr(node.orelse[-1], 'end_lineno', l_end)
            else_node = TheNode(id=else_id, ma='nguoc_lai', o={}, than=else_body, line_start=actual_else_start, line_end=else_end, indent=indent, duoi_dong='')
            return [if_node, else_node]
        return if_node
    return None

def _chuyen_danh_sach_ast_sang_the(statements: List[ast.stmt], lines: List[str], full_source: str, counter: List[int]) -> List[TheNode]:
    """Chuyển danh sách statement AST sang danh sách TheNode kèm các dòng chú thích giữa các câu lệnh."""
    res: List[TheNode] = []
    if not statements:
        return res
    current_line = getattr(statements[0], 'lineno', 1)
    for stmt in statements:
        st_l = getattr(stmt, 'lineno', current_line)
        en_l = getattr(stmt, 'end_lineno', st_l)
        if st_l > current_line:
            gap_lines = lines[current_line - 1:st_l - 1]
            idx = 0
            while idx < len(gap_lines):
                line_no = current_line + idx
                g_line = gap_lines[idx]
                s_g_line = g_line.strip()
                if s_g_line.startswith('#'):
                    counter[0] += 1
                    if _la_dong_ma_thuat(g_line, line_no):
                        res.append(TheNode(id=_tao_id('matho', counter[0]), ma='ma_tho', o={'nguyen_van': g_line}, than=[], line_start=line_no, line_end=line_no, indent=0, duoi_dong='', raw_text=g_line))
                    else:
                        res.append(TheNode(id=_tao_id('chuthich', counter[0]), ma='chu_thich', o={'noi_dung': s_g_line}, than=[], line_start=line_no, line_end=line_no, indent=len(g_line) - len(g_line.lstrip()), duoi_dong='', raw_text=g_line))
                    idx += 1
                else:
                    empty_start = line_no
                    empty_lines = []
                    while idx < len(gap_lines) and (not gap_lines[idx].strip().startswith('#')):
                        empty_lines.append(gap_lines[idx])
                        idx += 1
                    empty_text = '\n'.join(empty_lines)
                    if empty_text.strip():
                        counter[0] += 1
                        res.append(TheNode(id=_tao_id('matho', counter[0]), ma='ma_tho', o={'nguyen_van': empty_text}, than=[], line_start=empty_start, line_end=empty_start + len(empty_lines) - 1, indent=0, duoi_dong='', raw_text=empty_text))
        matched = _phan_tich_ast_statement(stmt, lines, full_source, counter)
        if matched is None:
            counter[0] += 1
            stmt_lines = lines[st_l - 1:en_l]
            text = '\n'.join(stmt_lines)
            res.append(TheNode(id=_tao_id('matho', counter[0]), ma='ma_tho', o={'nguyen_van': text}, than=[], line_start=st_l, line_end=en_l, indent=getattr(stmt, 'col_offset', 0), duoi_dong='', raw_text=text))
        elif isinstance(matched, list):
            res.extend(matched)
        else:
            res.append(matched)
        current_line = en_l + 1
    return res

def doc_tep_py_sang_cay_the(duong_dan: Path | str) -> FileSourceRecord:
    """Đọc tệp .py từ đĩa và phân tích thành FileSourceRecord & danh sách TheNode."""
    path = Path(duong_dan).resolve(strict=False)
    if not path.is_file():
        raise FileNotFoundError(f'Không tìm thấy tệp .py: {path}')
    raw_bytes = path.read_bytes()
    return doc_chuoi_py_sang_cay_the(raw_bytes, str(path))

def doc_chuoi_py_sang_cay_the(raw_bytes: bytes, duong_dan: Optional[str]=None) -> FileSourceRecord:
    """Phân tích chuỗi bytes của file .py thành cây thẻ với bảo toàn span dòng."""
    lines, newline = _tach_dong_va_newline(raw_bytes)
    full_source = raw_bytes.decode('utf-8', errors='replace')
    counter = [0]
    tree_nodes: List[TheNode] = []
    try:
        parsed_ast = ast.parse(full_source)
        current_line = 1
        for stmt in parsed_ast.body:
            st_l = getattr(stmt, 'lineno', current_line)
            en_l = getattr(stmt, 'end_lineno', st_l)
            if st_l > current_line:
                gap_lines = lines[current_line - 1:st_l - 1]
                idx = 0
                while idx < len(gap_lines):
                    line_no = current_line + idx
                    g_line = gap_lines[idx]
                    s_g_line = g_line.strip()
                    if s_g_line.startswith('#'):
                        counter[0] += 1
                        if _la_dong_ma_thuat(g_line, line_no):
                            tree_nodes.append(TheNode(id=_tao_id('matho', counter[0]), ma='ma_tho', o={'nguyen_van': g_line}, than=[], line_start=line_no, line_end=line_no, indent=0, duoi_dong='', raw_text=g_line))
                        else:
                            tree_nodes.append(TheNode(id=_tao_id('chuthich', counter[0]), ma='chu_thich', o={'noi_dung': s_g_line}, than=[], line_start=line_no, line_end=line_no, indent=len(g_line) - len(g_line.lstrip()), duoi_dong='', raw_text=g_line))
                        idx += 1
                    else:
                        empty_start = line_no
                        empty_lines = []
                        while idx < len(gap_lines) and (not gap_lines[idx].strip().startswith('#')):
                            empty_lines.append(gap_lines[idx])
                            idx += 1
                        empty_text = '\n'.join(empty_lines)
                        if empty_text.strip():
                            counter[0] += 1
                            tree_nodes.append(TheNode(id=_tao_id('matho', counter[0]), ma='ma_tho', o={'nguyen_van': empty_text}, than=[], line_start=empty_start, line_end=empty_start + len(empty_lines) - 1, indent=0, duoi_dong='', raw_text=empty_text))
            matched = _phan_tich_ast_statement(stmt, lines, full_source, counter)
            if matched is None:
                counter[0] += 1
                stmt_lines = lines[st_l - 1:en_l]
                text = '\n'.join(stmt_lines)
                tree_nodes.append(TheNode(id=_tao_id('matho', counter[0]), ma='ma_tho', o={'nguyen_van': text}, than=[], line_start=st_l, line_end=en_l, indent=getattr(stmt, 'col_offset', 0), duoi_dong='', raw_text=text))
            elif isinstance(matched, list):
                tree_nodes.extend(matched)
            else:
                tree_nodes.append(matched)
            current_line = en_l + 1
        if current_line <= len(lines):
            trailing_lines = lines[current_line - 1:]
            idx = 0
            while idx < len(trailing_lines):
                line_no = current_line + idx
                t_line = trailing_lines[idx]
                s_t_line = t_line.strip()
                if s_t_line.startswith('#'):
                    counter[0] += 1
                    if _la_dong_ma_thuat(t_line, line_no):
                        tree_nodes.append(TheNode(id=_tao_id('matho', counter[0]), ma='ma_tho', o={'nguyen_van': t_line}, than=[], line_start=line_no, line_end=line_no, indent=0, duoi_dong='', raw_text=t_line))
                    else:
                        tree_nodes.append(TheNode(id=_tao_id('chuthich', counter[0]), ma='chu_thich', o={'noi_dung': s_t_line}, than=[], line_start=line_no, line_end=line_no, indent=len(t_line) - len(t_line.lstrip()), duoi_dong='', raw_text=t_line))
                    idx += 1
                else:
                    empty_start = line_no
                    empty_lines = []
                    while idx < len(trailing_lines) and (not trailing_lines[idx].strip().startswith('#')):
                        empty_lines.append(trailing_lines[idx])
                        idx += 1
                    empty_text = '\n'.join(empty_lines)
                    if empty_text.strip():
                        counter[0] += 1
                        tree_nodes.append(TheNode(id=_tao_id('matho', counter[0]), ma='ma_tho', o={'nguyen_van': empty_text}, than=[], line_start=empty_start, line_end=empty_start + len(empty_lines) - 1, indent=0, duoi_dong='', raw_text=empty_text))
    except SyntaxError:
        counter[0] += 1
        full_text = '\n'.join(lines)
        tree_nodes = [TheNode(id=_tao_id('matho', counter[0]), ma='ma_tho', o={'nguyen_van': full_text}, than=[], line_start=1, line_end=len(lines), indent=0, duoi_dong='', raw_text=full_text)]
    return FileSourceRecord(duong_dan=duong_dan, raw_bytes=raw_bytes, newline=newline, lines=lines, tree=tree_nodes, has_modifications=False)

def sinh_dong_the_don(node: TheNode, indent_level: int=0) -> str:
    """Sinh chuỗi mã 1 dòng cho một TheNode duy nhất kèm duoi_dong."""
    spaces = ' ' * (indent_level * 4)
    ma = node.ma
    if ma == 'gan':
        ten_b = node.o.get('ten_bien', 'x')
        gia_t = node.o.get('gia_tri', '10')
        base = f'{spaces}{ten_b} = {gia_t}'
    elif ma == 'in_ra':
        noi_d = node.o.get('noi_dung', '')
        base = f'{spaces}print({noi_d})'
    elif ma == 'neu':
        dieu_k = node.o.get('dieu_kien', 'True')
        prefix = 'elif' if node.o.get('noi_tiep') == '1' else 'if'
        base = f'{spaces}{prefix} {dieu_k}:'
    elif ma == 'nguoc_lai':
        base = f'{spaces}else:'
    elif ma == 'nhap':
        tv = node.o.get('thu_vien', '').strip()
        ph = node.o.get('phan', '').strip()
        tk = node.o.get('ten_khac', '').strip()
        if ph:
            mot_ten = ',' not in ph
            if tk and mot_ten:
                base = f'{spaces}from {tv} import {ph} as {tk}'
            else:
                base = f'{spaces}from {tv} import {ph}'
        elif tk:
            base = f'{spaces}import {tv} as {tk}'
        else:
            base = f'{spaces}import {tv}'
    elif ma == 'dung_lap':
        base = f'{spaces}break'
    elif ma == 'bo_qua':
        base = f'{spaces}continue'
    elif ma == 'thu':
        base = f'{spaces}try:'
    elif ma == 'bat_loi':
        loai = node.o.get('loai_loi', '').strip() or 'Exception'
        tb = node.o.get('ten_bien', '').strip()
        base = f'{spaces}except {loai} as {tb}:' if tb else f'{spaces}except {loai}:'
    elif ma == 'lap_moi':
        bien = node.o.get('bien', 'i')
        day = node.o.get('day', 'range(10)')
        base = f'{spaces}for {bien} in {day}:'
    elif ma == 'lap_khi':
        dieu_k = node.o.get('dieu_kien', 'True')
        base = f'{spaces}while {dieu_k}:'
    elif ma == 'tra_ve':
        gia_t = node.o.get('gia_tri', '')
        base = f'{spaces}return {gia_t}'.rstrip()
    elif ma == 'ham':
        ten_ham = node.o.get('ten_ham', 'ham')
        tham_so = node.o.get('tham_so', '')
        kieu_tra_ve = node.o.get('kieu_tra_ve', '')
        prefix = 'async def' if node.o.get('async') == '1' else 'def'
        lines = []
        if node.o.get('trang_tri'):
            for dec in node.o['trang_tri'].split('\n'):
                if dec.strip():
                    lines.append(f'{spaces}{dec.strip()}')
        if kieu_tra_ve:
            if not kieu_tra_ve.startswith('->'):
                kieu_tra_ve = f'-> {kieu_tra_ve}'
            sig = f'{spaces}{prefix} {ten_ham}({tham_so}) {kieu_tra_ve}:'
        else:
            sig = f'{spaces}{prefix} {ten_ham}({tham_so}):'
        lines.append(sig)
        base = '\n'.join(lines)
    elif ma == 'goi_ham':
        ten_ham = node.o.get('ten_ham', 'ham')
        doi_so = node.o.get('doi_so', '')
        base = f'{spaces}{ten_ham}({doi_so})'
    elif ma == 'pheptinh':
        trai = node.o.get('trai', 'a')
        phep = node.o.get('phep', '+')
        phai = node.o.get('phai', 'b')
        base = f'{spaces}{trai} {phep} {phai}'
    elif ma == 'chu_thich':
        nd = node.o.get('noi_dung', '').strip()
        if not nd.startswith('#'):
            nd = f'# {nd}'
        base = f'{spaces}{nd}'
    elif ma == 'ma_tho':
        raw = node.o.get('nguyen_van', node.raw_text or '')
        return raw
    else:
        base = f'{spaces}pass'
    if node.duoi_dong:
        dd = node.duoi_dong
        if dd.lstrip().startswith('#') and (not dd.startswith(' ')):
            dd = ' ' + dd
        return f'{base}{dd}'
    return base

def sinh_ma_python(nodes: List[TheNode], indent_level: int=0) -> str:
    """Sinh toàn bộ mã Python từ danh sách TheNode (chuẩn 4 dấu cách)."""
    res_lines: List[str] = []
    for node in nodes:
        if node.ma == 'ma_tho':
            raw = node.o.get('nguyen_van', node.raw_text or '')
            if raw:
                spaces = ' ' * (indent_level * 4)
                for rl in raw.split('\n'):
                    if rl.strip():
                        res_lines.append(f'{spaces}{rl}')
                    else:
                        res_lines.append('')
            continue
        is_else_or_elif = node.ma in ('nguoc_lai', 'bat_loi') or (node.ma == 'neu' and node.o.get('noi_tiep') == '1')
        cur_indent = max(0, indent_level - 1) if is_else_or_elif else indent_level
        head_line = sinh_dong_the_don(node, cur_indent)
        res_lines.append(head_line)
        if BO_THE_V1.get(node.ma, TheDefinition('', '', '', [], False, '')).co_than:
            if node.than:
                child_indent = cur_indent + 1
                child_code = sinh_ma_python(node.than, child_indent)
                res_lines.append(child_code)
            else:
                spaces = ' ' * ((cur_indent + 1) * 4)
                res_lines.append(f'{spaces}pass')
    return '\n'.join(res_lines)

def luu_cay_the_ra_tep_py(record: FileSourceRecord) -> bytes:
    """Lưu cây thẻ ngược lại byte file .py.

    CỬA CỨNG 1: Nếu chưa sửa gì (has_modifications == False), trả về CHÍNH XÁC
    raw_bytes ban đầu (100% SHA-256 match, 0 byte thay đổi).

    CỬA CỨNG 2: Nếu có sửa, thực hiện thay thế trên các span dòng [line_start:line_end]
    của đúng các thẻ bị sửa (da_sua == True), giữ nguyên toàn bộ các dòng chú thích,
    import và duoi_dong (Mục 14.1).
    """
    if not record.has_modifications:
        return record.raw_bytes
    working_lines = list(record.lines)

    def _apply_node(n: TheNode, ind: int):
        node_or_child_modified = n.da_sua or any((c.da_sua for c in n.than))
        if node_or_child_modified:
            if n.line_start is not None and n.line_end is not None:
                new_code = sinh_ma_python([n], indent_level=ind)
                new_lines = new_code.split('\n')
                idx_s = n.line_start - 1
                idx_e = n.line_end
                working_lines[idx_s:idx_e] = new_lines
        else:
            for child in n.than:
                _apply_node(child, ind + 1)
    for node in record.tree:
        _apply_node(node, 0)
    result_text = record.newline.join(working_lines)
    return result_text.encode('utf-8')

@dataclass
class DiagnosticItem:
    muc_do: str
    ma_loi: str
    thong_diep: str
    node_id: str
    line: Optional[int] = None

@dataclass
class DiagnosticResult:
    hop_le: bool
    so_loi_do: int
    so_canh_bao_vang: int
    danh_sach: List[DiagnosticItem]
    so_lan_dung_the: Dict[str, int]

def _trich_xuat_bien_trong_bieu_thuc(bieu_thuc: str) -> Set[str]:
    """Phân tích AST biểu thức để lấy danh sách tên biến được đọc từ phạm vi ngoài."""
    if not bieu_thuc or not bieu_thuc.strip():
        return set()
    try:
        parsed = ast.parse(bieu_thuc, mode='eval')
        local_comp_vars: Set[str] = set()
        for node in ast.walk(parsed):
            if isinstance(node, (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)):
                for gen in node.generators:
                    for t_node in ast.walk(gen.target):
                        if isinstance(t_node, ast.Name):
                            local_comp_vars.add(t_node.id)
            elif isinstance(node, ast.NamedExpr):
                if isinstance(node.target, ast.Name):
                    local_comp_vars.add(node.target.id)
        names: Set[str] = set()
        for node in ast.walk(parsed):
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
                if node.id not in BUILTIN_SYMBOLS and node.id not in local_comp_vars:
                    names.add(node.id)
        return names
    except Exception:
        clean = re.sub('"(?:[^"\\\\]|\\\\.)*"', ' ', bieu_thuc)
        clean = re.sub("'(?:[^'\\\\]|\\\\.)*'", ' ', clean)
        clean = re.sub('\\.[a-zA-Z_][a-zA-Z0-9_]*', ' ', clean)
        tokens = set(re.findall('\\b[a-zA-Z_][a-zA-Z0-9_]*\\b', clean))
        return {t for t in tokens if t not in BUILTIN_SYMBOLS}

def _trich_xuat_bieu_tuong_import(code: str) -> Set[str]:
    """Trích xuất tất cả các tên được import từ khối mã thô."""
    symbols: Set[str] = set()
    if not code:
        return symbols
    try:
        tree = ast.parse(code)
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    symbols.add(alias.asname or alias.name.split('.')[0])
            elif isinstance(node, ast.ImportFrom):
                for alias in node.names:
                    if alias.name != '*':
                        symbols.add(alias.asname or alias.name)
    except Exception:
        for line in code.splitlines():
            line = line.strip()
            if line.startswith('import '):
                parts = line[7:].split(',')
                for p in parts:
                    p = p.strip().split(' as ')[-1].strip().split('.')[0]
                    if p:
                        symbols.add(p)
            elif line.startswith('from ') and ' import ' in line:
                _, imp = line.split(' import ', 1)
                for p in imp.split(','):
                    p = p.strip().replace('(', '').replace(')', '').split(' as ')[-1].strip()
                    if p and p != '*':
                        symbols.add(p)
    return symbols

def _trich_xuat_bien_gan_trong_ma_tho(code: str) -> Set[str]:
    """Trích xuất các biến/hàm/lớp được định nghĩa trong khối mã thô."""
    names: Set[str] = set()
    if not code:
        return names
    try:
        tree = ast.parse(code)
        for node in ast.walk(tree):
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
                names.add(node.id)
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                names.add(node.name)
    except Exception:
        for m in re.finditer('^\\s*([a-zA-Z_][a-zA-Z0-9_]*)\\s*=', code, re.MULTILINE):
            names.add(m.group(1))
        for m in re.finditer('^\\s*(?:def|class)\\s+([a-zA-Z_][a-zA-Z0-9_]*)', code, re.MULTILINE):
            names.add(m.group(1))
    return names

def _trich_xuat_ten_tham_so(tham_so_str: str) -> List[str]:
    """Trích xuất danh sách tên tham số từ chuỗi định nghĩa hàm."""
    if not tham_so_str or not tham_so_str.strip():
        return []
    try:
        mod = ast.parse(f'def _({tham_so_str}): pass')
        fn = mod.body[0]
        assert isinstance(fn, ast.FunctionDef)
        params = []
        for arg in fn.args.posonlyargs + fn.args.args + fn.args.kwonlyargs:
            params.append(arg.arg)
        if fn.args.vararg:
            params.append(fn.args.vararg.arg)
        if fn.args.kwarg:
            params.append(fn.args.kwarg.arg)
        return params
    except Exception:
        clean = re.sub('"(?:[^"\\\\]|\\\\.)*"', '""', tham_so_str)
        clean = re.sub("'(?:[^'\\\\]|\\\\.)*'", "''", clean)
        depth = 0
        cur = []
        chunks = []
        for ch in clean:
            if ch in '([{':
                depth += 1
            elif ch in ')]}':
                depth -= 1
            elif ch == ',' and depth == 0:
                chunks.append(''.join(cur).strip())
                cur = []
                continue
            cur.append(ch)
        if cur:
            chunks.append(''.join(cur).strip())
        res = []
        for chunk in chunks:
            if chunk == '*':
                continue
            part = re.split('[:=]', chunk)[0].strip().lstrip('*')
            if part and re.match('^[a-zA-Z_][a-zA-Z0-9_]*$', part):
                res.append(part)
        return res

def _dem_so_lan_dung_the(nodes: List[TheNode], counter: Dict[str, int]) -> None:
    """Duyệt đệ quy cây thẻ để đếm chính xác số lần dùng từng thẻ (×N)."""
    for n in nodes:
        counter[n.ma] = counter.get(n.ma, 0) - 1
        if n.than:
            _dem_so_lan_dung_the(n.than, counter)

def _thu_thap_bieu_tuong_toan_cuc(nodes: List[TheNode], global_symbols: Set[str]) -> None:
    """Pha 1: Thu thập biểu tượng toàn cục (hàm, import, gán trong mã thô)."""
    for node in nodes:
        if node.ma == 'ham':
            ten_h = node.o.get('ten_ham', '').strip()
            if ten_h:
                global_symbols.add(ten_h)
        elif node.ma == 'ma_tho':
            code = node.o.get('nguyen_van', node.raw_text or '')
            global_symbols.update(_trich_xuat_bieu_tuong_import(code))
            global_symbols.update(_trich_xuat_bien_gan_trong_ma_tho(code))
        elif node.ma == 'nhap':
            tv = node.o.get('thu_vien', '').strip()
            ph = node.o.get('phan', '').strip()
            tk = node.o.get('ten_khac', '').strip()
            if ph:
                mot_ten = ',' not in ph
                if tk and mot_ten:
                    global_symbols.add(tk)
                else:
                    for x in ph.split(','):
                        t = x.strip()
                        if re.fullmatch('[a-zA-Z_][a-zA-Z0-9_]*', t):
                            global_symbols.add(t)
            elif tk:
                global_symbols.add(tk)
            elif tv:
                goc = tv.split('.')[0].strip()
                if re.fullmatch('[a-zA-Z_][a-zA-Z0-9_]*', goc):
                    global_symbols.add(goc)
        if node.than:
            _thu_thap_bieu_tuong_toan_cuc(node.than, global_symbols)

def kiem_tra_cay_the(nodes: List[TheNode]) -> DiagnosticResult:
    """Chạy toàn bộ 5 quy tắc ĐỎ và 4 quy tắc VÀNG trên cây thẻ với Scope 2 pha."""
    diagnostics: List[DiagnosticItem] = []
    so_lan_dung: Dict[str, int] = {k: 0 for k in BO_THE_V1.keys()}
    _dem_so_lan_dung_the(nodes, so_lan_dung)
    global_symbols: Set[str] = set(BUILTIN_SYMBOLS)
    _thu_thap_bieu_tuong_toan_cuc(nodes, global_symbols)
    cac_bien_da_gan: Set[str] = set()
    cac_bien_da_doc: Set[str] = set()

    def _kiem_tra_danh_sach(node_list: List[TheNode], depth: int, inside_function: bool, scope_vars: Set[str], parent_ma: Optional[str]=None, inside_loop: bool=False):
        prev_node: Optional[TheNode] = None
        da_gap_tra_ve = False
        for idx, node in enumerate(node_list):
            ma = node.ma
            defn = BO_THE_V1.get(ma)
            if depth > 4:
                diagnostics.append(DiagnosticItem(muc_do='vang', ma_loi='excessive_nesting', thong_diep=f'Khối lệnh lồng quá sâu ({depth} tầng, tối đa 4)', node_id=node.id, line=node.line_start))
            if da_gap_tra_ve:
                diagnostics.append(DiagnosticItem(muc_do='vang', ma_loi='unreachable_code', thong_diep="Thẻ nằm sau lệnh 'Trả về', sẽ không bao giờ được chạy tới", node_id=node.id, line=node.line_start))
            if ma == 'tra_ve':
                da_gap_tra_ve = True
            if defn:
                for o_def in defn.o:
                    if o_def.bat_buoc:
                        val = node.o.get(o_def.ten, '')
                        if not val or not val.strip():
                            diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='empty_required_field', thong_diep=f"Ô bắt buộc '{o_def.ten}' của thẻ '{defn.ten}' còn trống", node_id=node.id, line=node.line_start))
            if ma == 'nguoc_lai':
                hop_le_else = parent_ma == 'neu' or (prev_node is not None and prev_node.ma == 'neu')
                if not hop_le_else:
                    diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='orphan_else', thong_diep="Thẻ 'Ngược lại' phải đứng ngay sau một thẻ 'Nếu'", node_id=node.id, line=node.line_start))
            if ma == 'tra_ve' and (not inside_function):
                diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='return_outside_function', thong_diep="Lệnh 'Trả về' chỉ được dùng bên trong một thẻ 'Hàm'", node_id=node.id, line=node.line_start))
            if ma in ('dung_lap', 'bo_qua') and (not inside_loop):
                diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='loop_control_outside_loop', thong_diep=f"Thẻ '{(defn.ten if defn else ma)}' chỉ được dùng bên trong 'Lặp mỗi' hoặc 'Lặp khi'", node_id=node.id, line=node.line_start))
            if ma == 'bat_loi':
                hop_le = parent_ma == 'thu' or (prev_node is not None and prev_node.ma == 'thu')
                if not hop_le:
                    diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='orphan_except', thong_diep="Thẻ 'Bắt lỗi' phải đứng ngay sau một thẻ 'Thử'", node_id=node.id, line=node.line_start))
            if ma == 'thu':
                sau = node_list[idx + 1] if idx + 1 < len(node_list) else None
                co_em = sau is not None and sau.ma == 'bat_loi'
                co_con = any((c is not None and c.ma == 'bat_loi' for c in node.than or []))
                if not co_em and (not co_con):
                    diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='try_without_except', thong_diep="Thẻ 'Thử' phải đi kèm một thẻ 'Bắt lỗi' ngay sau nó", node_id=node.id, line=node.line_start))
            if defn and defn.co_than and (not node.than):
                diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='empty_body', thong_diep=f"Thẻ '{defn.ten}' có thân nhưng chưa chứa lệnh nào bên trong", node_id=node.id, line=node.line_start))
            current_scope = set(scope_vars)
            if ma == 'gan':
                ten_bien = node.o.get('ten_bien', '').strip()
                gia_tri = node.o.get('gia_tri', '')
                read_vars = _trich_xuat_bien_trong_bieu_thuc(gia_tri)
                cac_bien_da_doc.update(read_vars)
                for v in read_vars:
                    if v not in current_scope:
                        diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='undefined_variable', thong_diep=f"Biến '{v}' được sử dụng nhưng chưa từng được gán giá trị", node_id=node.id, line=node.line_start))
                if ten_bien and re.match('^[a-zA-Z_][a-zA-Z0-9_]*$', ten_bien):
                    cac_bien_da_gan.add(ten_bien)
                    scope_vars.add(ten_bien)
            elif ma == 'in_ra':
                noi_dung = node.o.get('noi_dung', '')
                read_vars = _trich_xuat_bien_trong_bieu_thuc(noi_dung)
                cac_bien_da_doc.update(read_vars)
                for v in read_vars:
                    if v not in current_scope:
                        diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='undefined_variable', thong_diep=f"Biến '{v}' được sử dụng nhưng chưa từng được gán", node_id=node.id, line=node.line_start))
            elif ma == 'neu':
                dk = node.o.get('dieu_kien', '')
                read_vars = _trich_xuat_bien_trong_bieu_thuc(dk)
                cac_bien_da_doc.update(read_vars)
                for v in read_vars:
                    if v not in current_scope:
                        diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='undefined_variable', thong_diep=f"Biến '{v}' trong điều kiện 'Nếu' chưa được gán", node_id=node.id, line=node.line_start))
            elif ma == 'lap_khi':
                dk = node.o.get('dieu_kien', '')
                read_vars = _trich_xuat_bien_trong_bieu_thuc(dk)
                cac_bien_da_doc.update(read_vars)
                for v in read_vars:
                    if v not in current_scope:
                        diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='undefined_variable', thong_diep=f"Biến '{v}' trong điều kiện 'Lặp khi' chưa được gán", node_id=node.id, line=node.line_start))
                if read_vars and node.than:
                    assigned_in_body: Set[str] = set()
                    for child in node.than:
                        if child.ma == 'gan':
                            assigned_in_body.add(child.o.get('ten_bien', '').strip())
                    if not read_vars & assigned_in_body:
                        diagnostics.append(DiagnosticItem(muc_do='vang', ma_loi='potential_infinite_loop', thong_diep='Vòng lặp có thể lặp vô tận: không có biến điều kiện nào được thay đổi giá trị trong thân', node_id=node.id, line=node.line_start))
            elif ma == 'lap_moi':
                bien_lap = node.o.get('bien', '').strip()
                day_lap = node.o.get('day', '')
                read_vars = _trich_xuat_bien_trong_bieu_thuc(day_lap)
                cac_bien_da_doc.update(read_vars)
                for v in read_vars:
                    if v not in current_scope:
                        diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='undefined_variable', thong_diep=f"Biến dãy '{v}' trong 'Lặp mỗi' chưa được gán", node_id=node.id, line=node.line_start))
            elif ma == 'tra_ve':
                gt = node.o.get('gia_tri', '')
                read_vars = _trich_xuat_bien_trong_bieu_thuc(gt)
                cac_bien_da_doc.update(read_vars)
                for v in read_vars:
                    if v not in current_scope:
                        diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='undefined_variable', thong_diep=f"Biến '{v}' trong giá trị 'Trả về' chưa được gán", node_id=node.id, line=node.line_start))
            elif ma == 'pheptinh':
                t = node.o.get('trai', '')
                p = node.o.get('phai', '')
                read_vars = _trich_xuat_bien_trong_bieu_thuc(t) | _trich_xuat_bien_trong_bieu_thuc(p)
                cac_bien_da_doc.update(read_vars)
                for v in read_vars:
                    if v not in current_scope:
                        diagnostics.append(DiagnosticItem(muc_do='do', ma_loi='undefined_variable', thong_diep=f"Biến '{v}' trong phép tính chưa được gán", node_id=node.id, line=node.line_start))
            if node.than:
                child_scope = set(scope_vars)
                is_fn = inside_function or ma == 'ham'
                if ma == 'ham':
                    ten_h = node.o.get('ten_ham', '').strip()
                    if ten_h:
                        scope_vars.add(ten_h)
                        cac_bien_da_gan.add(ten_h)
                    params = _trich_xuat_ten_tham_so(node.o.get('tham_so', ''))
                    child_scope.update(params)
                    cac_bien_da_gan.update(params)
                elif ma == 'lap_moi':
                    b_str = node.o.get('bien', '').strip()
                    loop_vars = re.findall('\\b[a-zA-Z_][a-zA-Z0-9_]*\\b', b_str)
                    for b in loop_vars:
                        child_scope.add(b)
                        cac_bien_da_gan.add(b)
                elif ma == 'bat_loi':
                    tb = node.o.get('ten_bien', '').strip()
                    if re.fullmatch('[a-zA-Z_][a-zA-Z0-9_]*', tb):
                        child_scope.add(tb)
                        cac_bien_da_gan.add(tb)
                if ma in ('lap_moi', 'lap_khi'):
                    trong_lap = True
                elif ma == 'ham':
                    trong_lap = False
                else:
                    trong_lap = inside_loop
                _kiem_tra_danh_sach(node.than, depth=depth + 1, inside_function=is_fn, scope_vars=child_scope, parent_ma=ma, inside_loop=trong_lap)
            prev_node = node
    _kiem_tra_danh_sach(nodes, depth=1, inside_function=False, scope_vars=set(global_symbols), inside_loop=False)
    chua_dung = cac_bien_da_gan - cac_bien_da_doc - global_symbols
    for var in sorted(chua_dung):
        if not var.startswith('_'):
            diagnostics.append(DiagnosticItem(muc_do='vang', ma_loi='unused_variable', thong_diep=f"Biến '{var}' đã được khai báo nhưng chưa được sử dụng lần nào", node_id='global'))
    so_do = sum((1 for d in diagnostics if d.muc_do == 'do'))
    so_vang = sum((1 for d in diagnostics if d.muc_do == 'vang'))
    return DiagnosticResult(hop_le=so_do == 0, so_loi_do=so_do, so_canh_bao_vang=so_vang, danh_sach=diagnostics, so_lan_dung_the=so_lan_dung)

@dataclass
class ExecutionResult:
    exit_code: int
    stdout: str
    stderr: str
    wall_time_ms: int
    timed_out: bool
    status: str

def chay_ma_tien_trinh_rieng(code: str, timeout: float=5.0) -> ExecutionResult:
    """Chạy mã Python người dùng trong một tiến trình con riêng, trần 5 giây.

    TÊN CŨ LÀ `chay_ma_python_sandbox` — ĐỔI NGÀY 25/08/2026.

    Chú thích cũ đã nói đúng ("đây KHÔNG PHẢI hộp cát"), nhưng cái TÊN nói
    ngược lại, và cái tên là thứ người sau đọc. Ai gọi `..._sandbox` sẽ tin
    là đã cô lập, rồi dựa vào đó mà quyết định.

    ĐO THẬT 25/08/2026, chạy qua đúng hàm này, không đọc mã mà suy:

        ghi tệp bằng đường dẫn TUYỆT ĐỐI ngoài cwd   GHI ĐƯỢC
        gọi tiến trình con (`cmd /c echo`)           CHẠY ĐƯỢC
        mở socket, lắng nghe                         MỞ ĐƯỢC (cổng 57658)
        đọc tệp bất kỳ trên đĩa                      ĐỌC ĐƯỢC
        đọc biến môi trường                          ĐỌC ĐƯỢC

    Thứ duy nhất hàm này có: tiến trình riêng + trần 5 giây. Hai thứ ấy chống
    lặp vô hạn và chống treo app. Chúng KHÔNG chống mã phá hoại, và không có
    giới hạn RAM, hệ tệp, mạng hay tiến trình nào cả.

    Kế hoạch 19/08 từng hứa "giới hạn 256 MB RAM" (`import resource` — API
    Unix, Windows không có) và "cwd ở thư mục tạm, không cấp quyền ghi ra
    ngoài" (chạy thử: ghi được). Cả hai lời hứa ấy chưa bao giờ tồn tại.

    Dùng được cho: người dùng chạy mã CỦA CHÍNH HỌ trên máy CỦA CHÍNH HỌ —
    đúng quyền họ vốn có khi mở `python` lên gõ.
    Không dùng được cho: máy chủ nhiều người, hoặc chạy mã tải từ nơi khác.
    """
    t_start = time.perf_counter()
    timed_out = False
    with tempfile.TemporaryDirectory(prefix='aura_the_run_') as tmpdir:
        script_file = Path(tmpdir) / 'run_script.py'
        script_file.write_text(code, encoding='utf-8')
        try:
            proc = subprocess.Popen([sys.executable, str(script_file)], cwd=tmpdir, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding='utf-8', errors='replace')
            stdout, stderr = proc.communicate(timeout=timeout)
            exit_code = proc.returncode
        except subprocess.TimeoutExpired:
            timed_out = True
            proc.kill()
            stdout, stderr = proc.communicate()
            exit_code = 124
            stderr += f'\n[TIMEOUT]: Quá giới hạn thời gian thực thi {timeout:.1f} giây. Tiến trình đã bị dừng.'
    t_end = time.perf_counter()
    wall_time_ms = int((t_end - t_start) * 1000)
    if timed_out:
        status = 'TIMEOUT'
    elif exit_code == 0:
        status = 'PASS'
    else:
        status = 'ERROR'
    return ExecutionResult(exit_code=exit_code, stdout=stdout, stderr=stderr, wall_time_ms=wall_time_ms, timed_out=timed_out, status=status)

"""the_v1.py — Bộ lõi hệ thống Lập trình bằng THẺ (bản v1).

Thiết kế theo chuẩn AURA v3 và chỉ đạo của Sếp (19/08/2026):
1. 11 thẻ: 10 thẻ ngôn ngữ cố định + 1 thẻ Mã Thô (`ma_tho`, màu xám #6B7280).
2. CỬA CỨNG 1: Mở tệp .py bất kỳ -> Lưu -> Giữ nguyên 100% byte gốc (SHA-256 khớp).
3. CỬA CỨNG 2: Sửa 1 ô -> Giữ nguyên chú thích cuối dòng (cắt bằng end_col_offset) và
   không đổi các dòng còn lại.
4. Kiểm tra tĩnh: 5 lỗi ĐỎ (lỗi cứng) và 4 cảnh báo VÀNG (rủi ro).
5. Thực thi: Tiến trình riêng + trần giờ 5.0s.
"""
from __future__ import annotations
import ast
import re
import subprocess
import sys
import tempfile
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Dict, List, Optional, Set, Tuple
BUILTIN_SYMBOLS: Set[str] = {'True', 'False', 'None', 'range', 'len', 'int', 'str', 'float', 'list', 'dict', 'set', 'tuple', 'sum', 'min', 'max', 'abs', 'round', 'bool', 'print', 'input', 'enumerate', 'zip', 'sorted', 'reversed', 'map', 'filter', 'open', 'type', 'isinstance', 'issubclass', 'iter', 'next', 'all', 'any', 'chr', 'ord', 'hex', 'bin', 'oct', 'pow', 'divmod', 'format', 'repr', 'getattr', 'hasattr', 'setattr', 'delattr', 'frozenset', 'callable', 'id', 'hash', 'staticmethod', 'classmethod', 'property', 'super', 'vars', 'dir', 'bytes', 'bytearray', 'slice', 'complex', 'memoryview', 'ascii', 'help', 'globals', 'locals', 'Exception', 'ValueError', 'TypeError', 'KeyError', 'IndexError', 'AttributeError', 'RuntimeError', 'StopIteration', 'FileNotFoundError', 'AssertionError', 'ImportError', 'IOError', 'OSError', 'if', 'else', 'elif', 'for', 'while', 'in', 'is', 'not', 'and', 'or', 'as', 'with', 'try', 'except', 'finally', 'def', 'class'}
NHOM_THE: Dict[str, Dict[str, str]] = {'dieu_khien': {'ten': 'Điều khiển', 'mau': '#3B82F6'}, 'du_lieu': {'ten': 'Dữ liệu', 'mau': '#10B981'}, 'vao_ra': {'ten': 'Vào / Ra', 'mau': '#8B5CF6'}, 'ham': {'ten': 'Hàm', 'mau': '#F59E0B'}, 'chu_thich': {'ten': 'Chú thích', 'mau': '#14B8A6'}, 'ma_tho': {'ten': 'Mã thô', 'mau': '#6B7280'}}

@dataclass(frozen=True)
class ODefinition:
    ten: str
    kieu: str
    bat_buoc: bool = True
    goi_y: str = ''

@dataclass(frozen=True)
class TheDefinition:
    ma: str
    ten: str
    nhom: str
    o: List[ODefinition]
